import{_ as e,o as s,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"插件","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/plugins.md","filePath":"zh-CN/user-guide/settings/plugins.md","lastUpdated":1784031483000}'),n={name:"zh-CN/user-guide/settings/plugins.md"};function o(i,t,p,g,l,d){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h1><p>列出所有已安装的插件，页面头部的徽标会显示当前加载的 Plugin SDK 版本(如果要对照 <a href="./../../dev-guide/">开发手册</a>开发插件，这个版本号很有用)。</p><h2 id="每个插件的卡片" tabindex="-1">每个插件的卡片 <a class="header-anchor" href="#每个插件的卡片" aria-label="Permalink to &quot;每个插件的卡片&quot;">​</a></h2><p>每个已安装的插件都有一张卡片，显示图标、名称、版本号、DLL 文件名以及插件的<strong>总体功能简介</strong>。</p><p>点击卡片可以展开，查看它注册的功能组件，按类型分组（搜索源、动态菜单提供者等）——每个可切换的组件都有自己的<strong>启用/禁用复选框</strong>；标记为必要项的组件会显示一个锁形图标，不能关闭。将鼠标悬停在各组件上时，会弹出该组件的<strong>详细功能说明 ToolTip</strong>。</p><p>当某个分组（或整个插件）有 2 个及以上可切换组件时，标题旁会出现一个<strong>全选/全不选</strong>链接，点击即可一次性切换该范围内的所有复选框，不用逐个手动勾选。</p><p>如果插件暴露了自己的配置项(超出简单启用/禁用的范畴)，卡片头部会出现一个<strong>配置</strong>按钮，点击会打 开该插件自己的设置对话框。</p><p>页面底部有一条提示横幅，说明部分组件的开关改动需要重启 SwiftList 才能生效。</p><p>如果没有安装任何插件，页面会显示一个空状态提示。</p><p>想看插件自己的<strong>配置</strong>对话框实际长什么样、能改什么(比如改一个触发关键词)，可以参考 <a href="./../instant-answers.html">即时答案与关键词功能</a>。</p>',10)])])}const h=e(n,[["render",o]]);export{_ as __pageData,h as default};
